  <?php $url=SupportRequests::attachmentUrl($item->attachment); if($url): ?><a class="btn btn-outline-primary mb-4" href="<?php echo $esc($url); ?>" target="_blank" rel="noopener">Xem tệp đính kèm</a><?php endif; ?>
